// SystemVariableScope reports whether a known MySQL 8.0 system variable is
// global-only or session-only; a variable with both scopes is neither.
func SystemVariableScope(name string) (globalOnly, sessionOnly bool) {
	_, globalOnly = globalOnlySystemVariables[name]
	_, sessionOnly = sessionOnlySystemVariables[name]
	return globalOnly, sessionOnly
}
